create extension if not exists pgcrypto;
create type public.brand_code as enum ('ARRA','SQUATCH');
create type public.member_role as enum ('owner','admin','member','client');
create type public.work_status as enum ('not_started','in_progress','needs_approval','revisions','complete','cancelled');
create type public.priority_level as enum ('low','normal','high','urgent');
create type public.approval_status as enum ('pending','approved','changes_requested','withdrawn');
create type public.link_kind as enum ('working','review','final');

create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', avatar_url text, email text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null default 'member', title text, active boolean not null default true, created_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.brands (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, code public.brand_code not null, name text not null, color text not null, created_at timestamptz not null default now(), unique(workspace_id,code));
create table public.clients (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, brand_id uuid references public.brands(id), name text not null, slug text not null, status text not null default 'active', primary_contact_name text, primary_contact_email text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,slug));
create table public.projects (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, brand_id uuid not null references public.brands(id), name text not null, description text, status public.work_status not null default 'not_started', priority public.priority_level not null default 'normal', owner_id uuid references public.profiles(id), start_date date, due_date date, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, client_id uuid references public.clients(id) on delete set null, brand_id uuid not null references public.brands(id), parent_task_id uuid references public.tasks(id) on delete cascade, title text not null, description text, status public.work_status not null default 'not_started', priority public.priority_level not null default 'normal', assignee_id uuid references public.profiles(id), reporter_id uuid references public.profiles(id), start_date date, due_date date, position numeric not null default 0, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.deliverables (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, task_id uuid references public.tasks(id) on delete set null, client_id uuid not null references public.clients(id), brand_id uuid not null references public.brands(id), title text not null, description text, status public.work_status not null default 'not_started', priority public.priority_level not null default 'normal', owner_id uuid references public.profiles(id), due_date date, revision_round integer not null default 0 check(revision_round>=0), delivered_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.deliverable_links (id uuid primary key default gen_random_uuid(), deliverable_id uuid not null references public.deliverables(id) on delete cascade, kind public.link_kind not null, url text not null, label text, version integer not null default 1, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), unique(deliverable_id,kind,version));
create table public.approvals (id uuid primary key default gen_random_uuid(), deliverable_id uuid not null references public.deliverables(id) on delete cascade, requested_by uuid references public.profiles(id), reviewer_id uuid references public.profiles(id), reviewer_name text, reviewer_email text, status public.approval_status not null default 'pending', message text, requested_at timestamptz not null default now(), responded_at timestamptz);
create table public.revisions (id uuid primary key default gen_random_uuid(), deliverable_id uuid not null references public.deliverables(id) on delete cascade, approval_id uuid references public.approvals(id) on delete set null, round integer not null check(round>0), notes text not null, status public.work_status not null default 'revisions', requested_by uuid references public.profiles(id), assigned_to uuid references public.profiles(id), due_date date, resolved_at timestamptz, created_at timestamptz not null default now(), unique(deliverable_id,round));
create table public.comments (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, author_id uuid not null references public.profiles(id), task_id uuid references public.tasks(id) on delete cascade, project_id uuid references public.projects(id) on delete cascade, deliverable_id uuid references public.deliverables(id) on delete cascade, parent_id uuid references public.comments(id) on delete cascade, body text not null, edited_at timestamptz, created_at timestamptz not null default now(), constraint one_comment_parent check(num_nonnulls(task_id,project_id,deliverable_id)=1));
create table public.activity_events (id bigint generated always as identity primary key, workspace_id uuid not null references public.workspaces(id) on delete cascade, actor_id uuid references public.profiles(id), entity_type text not null, entity_id uuid not null, action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.saved_views (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, name text not null, entity_type text not null, filters jsonb not null default '{}', sort jsonb not null default '[]', is_shared boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, body text, entity_type text, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now());

create index idx_members_user on public.workspace_members(user_id) where active;
create index idx_clients_workspace_brand on public.clients(workspace_id,brand_id);
create index idx_projects_workspace_due on public.projects(workspace_id,due_date) where status not in ('complete','cancelled');
create index idx_projects_client on public.projects(client_id);
create index idx_tasks_today on public.tasks(workspace_id,due_date,status) where status not in ('complete','cancelled');
create index idx_tasks_assignee on public.tasks(assignee_id,status,due_date);
create index idx_tasks_project on public.tasks(project_id);
create index idx_deliverables_due on public.deliverables(workspace_id,due_date,status);
create index idx_approvals_pending on public.approvals(deliverable_id,status) where status='pending';
create index idx_comments_task on public.comments(task_id,created_at);
create index idx_comments_deliverable on public.comments(deliverable_id,created_at);
create index idx_activity_entity on public.activity_events(entity_type,entity_id,created_at desc);
create index idx_notifications_unread on public.notifications(user_id,created_at desc) where read_at is null;

create function public.is_workspace_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members where workspace_id=target and user_id=auth.uid() and active) $$;
create function public.is_workspace_admin(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members where workspace_id=target and user_id=auth.uid() and active and role in ('owner','admin')) $$;
create function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email,new.raw_user_meta_data->>'avatar_url'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
do $$ declare t text; begin foreach t in array array['workspaces','profiles','clients','projects','tasks','deliverables','saved_views'] loop execute format('create trigger touch_%I before update on public.%I for each row execute procedure public.touch_updated_at()',t,t); end loop; end $$;

alter table public.workspaces enable row level security; alter table public.profiles enable row level security; alter table public.workspace_members enable row level security; alter table public.brands enable row level security; alter table public.clients enable row level security; alter table public.projects enable row level security; alter table public.tasks enable row level security; alter table public.deliverables enable row level security; alter table public.deliverable_links enable row level security; alter table public.approvals enable row level security; alter table public.revisions enable row level security; alter table public.comments enable row level security; alter table public.activity_events enable row level security; alter table public.saved_views enable row level security; alter table public.notifications enable row level security;
create policy "profiles visible to coworkers" on public.profiles for select using(id=auth.uid() or exists(select 1 from public.workspace_members mine join public.workspace_members theirs using(workspace_id) where mine.user_id=auth.uid() and theirs.user_id=profiles.id));
create policy "profile owner updates" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "members read workspaces" on public.workspaces for select using(public.is_workspace_member(id));
create policy "members read memberships" on public.workspace_members for select using(public.is_workspace_member(workspace_id));
create policy "admins manage memberships" on public.workspace_members for all using(public.is_workspace_admin(workspace_id)) with check(public.is_workspace_admin(workspace_id));
do $$ declare t text; begin foreach t in array array['brands','clients','projects','tasks','deliverables','comments','activity_events','saved_views','notifications'] loop execute format('create policy "members read %1$s" on public.%1$I for select using(public.is_workspace_member(workspace_id))',t); execute format('create policy "members write %1$s" on public.%1$I for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id))',t); end loop; end $$;
create policy "members read deliverable links" on public.deliverable_links for select using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
create policy "members write deliverable links" on public.deliverable_links for all using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
create policy "members read approvals" on public.approvals for select using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
create policy "members write approvals" on public.approvals for all using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
create policy "members read revisions" on public.revisions for select using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
create policy "members write revisions" on public.revisions for all using(exists(select 1 from public.deliverables d where d.id=deliverable_id and public.is_workspace_member(d.workspace_id)));
